    <div class="col-md-3"><label class="form-label" for="cluster-species">Species</label><select class="form-select" id="cluster-species" name="species_id"><option value="">All species</option><?php foreach ($species as $item): ?><option value="<?= (int) $item['id'] ?>" <?= (int) $speciesFilter === (int) $item['id'] ? 'selected' : '' ?>><?= e($item['common_name']) ?> — <?= e($item['scientific_name']) ?></option><?php endforeach; ?></select></div>
